//! A/B probe generated by `cargo xtask ab init`. Write the cases in
//! `cases.rs`; run them with `cargo xtask ab bench` and `cargo xtask ab diff`.
//!
//! `ab-probe bench <case> <base|head>` runs one side of a benchmark case and
//! prints `ns=<elapsed> sum=<checksum>`. `ab-probe diff <case> <first-seed>
//! <count>` runs a differential case over a seed range, prints the first
//! mismatch and exits 1 when one is found. Exit 2 means a bad command line or
//! an unknown case.

mod cases;

use std::process::ExitCode;
use std::time::Instant;

/// Which copy of the crates a benchmark side runs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    /// The crates at the base revision (`base_*` aliases).
    Base,
    /// The crates in the working tree (`head_*` aliases).
    Head,
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let args: Vec<&str> = args.iter().map(String::as_str).collect();
    match args.as_slice() {
        ["bench", case, side] => {
            let side = match *side {
                "base" => Side::Base,
                "head" => Side::Head,
                other => {
                    eprintln!("unknown side `{other}`, expected base or head");
                    return ExitCode::from(2);
                }
            };
            let start = Instant::now();
            // `__empty` measures the process overhead that `ab bench` subtracts.
            let result = if *case == "__empty" {
                Some(0)
            } else {
                cases::bench(case, side)
            };
            let Some(sum) = result else {
                eprintln!("unknown bench case `{case}`");
                return ExitCode::from(2);
            };
            let ns = start.elapsed().as_nanos();
            println!("ns={ns} sum={sum}");
            ExitCode::SUCCESS
        }
        ["diff", case, first, count] => {
            let (Ok(first), Ok(count)) = (first.parse::<u64>(), count.parse::<u64>()) else {
                eprintln!("seeds must be unsigned integers");
                return ExitCode::from(2);
            };
            if count == 0 && cases::diff(case, first).is_none() {
                eprintln!("unknown diff case `{case}`");
                return ExitCode::from(2);
            }
            for seed in first..first.saturating_add(count) {
                match cases::diff(case, seed) {
                    None => {
                        eprintln!("unknown diff case `{case}`");
                        return ExitCode::from(2);
                    }
                    Some(Err(mismatch)) => {
                        println!("mismatch at seed {seed}: {mismatch}");
                        return ExitCode::from(1);
                    }
                    Some(Ok(())) => {}
                }
            }
            println!("ok: {count} seeds from {first} agree");
            ExitCode::SUCCESS
        }
        _ => {
            eprintln!("usage: ab-probe bench <case> <base|head> | ab-probe diff <case> <first-seed> <count>");
            ExitCode::from(2)
        }
    }
}

/// A small seeded generator (xorshift64*) for differential inputs.
#[allow(dead_code)]
pub struct Rng(u64);

#[allow(dead_code)]
impl Rng {
    /// A generator for `seed`; every seed, including 0, gives a usable state.
    pub fn new(seed: u64) -> Self {
        Self(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1)
    }

    /// The next 64 random bits.
    pub fn next_u64(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    /// A value in `0..n`; `n` must be non-zero.
    pub fn below(&mut self, n: u64) -> u64 {
        self.next_u64() % n
    }

    /// One element of `items`, which must be non-empty.
    pub fn pick<'a, T>(&mut self, items: &'a [T]) -> &'a T {
        &items[self.below(items.len() as u64) as usize]
    }
}
